window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4f0114d0b495006d"]={"versions": [{"id": "FIG-4f0114d0b495006d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Dateidiagramm zur Header-Dateistruktur und Include-Hierarchie des Debugging-Moduls (<code>Dbg</code>) innerhalb der AUTOSAR Classic Platform-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm unterscheidet Quellcodedateien (<code>«source»</code>) und Header-Dateien (<code>«header»</code>), verknüpft über gerichtete <code>«includes»</code>-Abhängigkeiten:</p>\n<ul class=\"fig-list\"><li><code>Dbg.c</code>: Zentrales BSW-Quelldateimodul. Inkludiert direkt:\n<ul class=\"fig-list\"><li><code>MemMap.h</code> (Speicherzuordnung)\n</li><li><code>Dbg.h</code> (Haupt-Header)\n</li><li><code>Dbg_Cfg.h</code> (Konfigurations-Header)\n</li><li><code>Dbg_Cbk.h</code> (Callback-Definitionen)\n</li><li><code>Dbg_Com.h</code> (Kommunikationsschnittstelle)\n</li><li><code>Det.h</code> (stereotypisiert als <code>«includes,optional»</code>, über Notiz annotiert: <em>„included, if development error detection is turned on“</em>)\n</li><li><code>Gpt.h</code> (General Purpose Timer)\n</li><li><code>PduR_Com.h</code> (PDU-Router-Kommunikation)\n</li><li><code>SchM_Dbg.h</code> (Scheduler-Modul-Schnittstelle)\n</li><li><code>&lt;MSN&gt;_Dbg.h</code> (modulspezifischer Debug-Header, Modul-Short-Name-Platzhalter)\n</li></ul>\n</li><li><code>Dbg.h</code>: Inkludiert <code>Std_Types.h</code>.\n</li><li><code>Std_Types.h</code>: Inkludiert <code>Platform_Types.h</code> und <code>Compiler.h</code>.\n</li><li><code>Dbg_Rte_Hook.c</code>: Eigenständige Quelldatei, annotiert mit Kommentar <em>„hook functions for the RTE generated by Dbg“</em>. Inkludiert <code>Dbg_Rte_Hook.h</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Dateieinbindungsmodell zur Kompilierzeit; kein dynamisches Laufzeit- oder Sequenzverhalten dargestellt. Die Include-Pfeile bilden die Übersetzungsabhängigkeiten des Präprozessors ab.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Vorgabe für Dateibenennung und Include-Struktur bei der Modulimplementierung von <code>Dbg</code>. Die Einbindung von <code>Det.h</code> ist bedingt und an das Aktivierungsflag der Entwicklungsauswertung gekoppelt. Modulspezifische Hook- und Callout-Header (<code>&lt;MSN&gt;_Dbg.h</code>) sowie die RTE-Hook-Dateien sind strikt von der internen Modul-Kernstruktur getrennt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0aa8a08da3aa6122", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Dateidiagramm zur Header-Dateistruktur und Include-Hierarchie des Debugging-Moduls (<code>Dbg</code>) innerhalb der AUTOSAR Classic Platform-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm unterscheidet Quellcodedateien (<code>«source»</code>) und Header-Dateien (<code>«header»</code>), verknüpft über gerichtete <code>«includes»</code>-Abhängigkeiten:</p>\n<ul class=\"fig-list\"><li><code>Dbg.c</code>: Zentrales BSW-Quelldateimodul. Inkludiert direkt:\n<ul class=\"fig-list\"><li><code>Dbg_MemMap.h</code> (modulspezifische Speicherzuordnung)\n</li><li><code>Dbg.h</code> (Haupt-Header)\n</li><li><code>Dbg_Cfg.h</code> (Konfigurations-Header)\n</li><li><code>Dbg_Cbk.h</code> (Callback-Definitionen)\n</li><li><code>Dbg_Com.h</code> (Kommunikationsschnittstelle)\n</li><li><code>Det.h</code> (stereotypisiert als <code>«includes,optional»</code>, annotiert mit: <em>„included, if development error detection is turned on“</em>)\n</li><li><code>Gpt.h</code> (General Purpose Timer)\n</li><li><code>PduR_Com.h</code> (PDU-Router-Kommunikation)\n</li><li><code>SchM_Dbg.h</code> (Scheduler-Modul-Schnittstelle)\n</li><li><code>&lt;MSN&gt;_Dbg.h</code> (modulspezifischer Debug-Header)\n</li></ul>\n</li><li><code>Dbg.h</code>: Inkludiert <code>Std_Typesh</code> (Schreibweise der Standard-Typen-Header-Datei).\n</li><li><code>Std_Typesh</code>: Inkludiert <code>Platform_Types.h</code> und <code>Compiler.h</code>.\n</li><li><code>Dbg_Rte_Hook.c</code>: Eigenständige Quelldatei, annotiert mit Notiz <em>„hook functions for the RTE generated by Dbg“</em>. Inkludiert <code>Dbg_Rte_Hook.h</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Dateieinbindungsmodell zur Kompilierzeit; kein dynamisches Laufzeit- oder Sequenzverhalten dargestellt. Die Include-Pfeile bilden die Übersetzungsabhängigkeiten des Präprozessors ab.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Vorgabe für Dateibenennung und Include-Struktur bei der Modulimplementierung von <code>Dbg</code>. Die Einbindung der Speicherzuordnung erfolgt über den modulspezifischen Header <code>Dbg_MemMap.h</code>. Die Einbindung von <code>Det.h</code> ist bedingt und an die Aktivierung der Entwicklungsauswertung gekoppelt. Modulspezifische Debug-Header (<code>&lt;MSN&gt;_Dbg.h</code>) und die generierten RTE-Hook-Dateien sind von der internen Modul-Kernstruktur getrennt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3dc70b695787c1de", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Dateidiagramm zur Header-Dateistruktur und Include-Hierarchie des Debugging-Moduls (<code>Dbg</code>) innerhalb der AUTOSAR Classic Platform-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm unterscheidet Quellcodedateien (<code>«source»</code>) und Header-Dateien (<code>«header»</code>), verknüpft über gerichtete <code>«includes»</code>-Abhängigkeiten:</p>\n<ul class=\"fig-list\"><li><code>Dbg.c</code>: Zentrales BSW-Quelldateimodul. Inkludiert direkt:\n<ul class=\"fig-list\"><li><code>Dbg_MemMap.h</code> (modulspezifische Speicherzuordnung)\n</li><li><code>Dbg.h</code> (Haupt-Header)\n</li><li><code>Dbg_Cfg.h</code> (Konfigurations-Header)\n</li><li><code>Dbg_Cbk.h</code> (Callback-Definitionen)\n</li><li><code>Dbg_Com.h</code> (Kommunikationsschnittstelle)\n</li><li><code>Det.h</code> (stereotypisiert als <code>«includes,optional»</code>, annotiert mit: <em>„included, if development error detection is turned on“</em>)\n</li><li><code>Gpt.h</code> (General Purpose Timer)\n</li><li><code>PduR_Com.h</code> (PDU-Router-Kommunikation)\n</li><li><code>SchM_Dbg.h</code> (Scheduler-Modul-Schnittstelle)\n</li><li><code>&lt;MSN&gt;_Dbg.h</code> (modulspezifischer Debug-Header)\n</li></ul>\n</li><li><code>Dbg.h</code>: Inkludiert <code>Std_Typesh</code> (Schreibweise der Standard-Typen-Header-Datei).\n</li><li><code>Std_Typesh</code>: Inkludiert <code>Platform_Types.h</code> und <code>Compiler.h</code>.\n</li><li><code>Dbg_Rte_Hook.c</code>: Eigenständige Quelldatei, annotiert mit Notiz <em>„hook functions for the RTE generated by Dbg“</em>. Inkludiert <code>Dbg_Rte_Hook.h</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Dateieinbindungsmodell zur Kompilierzeit; kein dynamisches Laufzeit- oder Sequenzverhalten dargestellt. Die Include-Pfeile bilden die Übersetzungsabhängigkeiten des Präprozessors ab.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Vorgabe für Dateibenennung und Include-Struktur bei der Modulimplementierung von <code>Dbg</code>. Die Einbindung der Speicherzuordnung erfolgt über den modulspezifischen Header <code>Dbg_MemMap.h</code>. Die Einbindung von <code>Det.h</code> ist bedingt und an die Aktivierung der Entwicklungsauswertung gekoppelt. Modulspezifische Debug-Header (<code>&lt;MSN&gt;_Dbg.h</code>) und die generierten RTE-Hook-Dateien sind von der internen Modul-Kernstruktur getrennt.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-4f0114d0b495006d", "to": "FIG-0aa8a08da3aa6122", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>MemMap.h</code>: Umbenannt zu <code>Dbg_MemMap.h</code>.\n</li><li><code>Std_Types.h</code>: Typografischer Schreibfehler in der Header-Bezeichnung (<code>Std_Typesh</code> statt <code>Std_Types.h</code>).\n</li></ul>"}, {"from": "FIG-0aa8a08da3aa6122", "to": "FIG-3dc70b695787c1de", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
